let seedPromise;async function seed(db){await db.batch([db.prepare(`CREATE TABLE IF NOT EXISTS categories(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT UNIQUE,slug TEXT UNIQUE,icon TEXT)`),db.prepare(`CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,phone TEXT UNIQUE,role TEXT,district TEXT)`),db.prepare(`CREATE TABLE IF NOT EXISTS listings(id INTEGER PRIMARY KEY AUTOINCREMENT,seller_id INTEGER,category_id INTEGER,title TEXT,description TEXT,price INTEGER,condition TEXT DEFAULT 'new',status TEXT DEFAULT 'active',district TEXT,city TEXT DEFAULT 'Kendari',province TEXT DEFAULT 'Sulawesi Tenggara',views INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP)`),db.prepare(`CREATE TABLE IF NOT EXISTS analytics_events(id INTEGER PRIMARY KEY AUTOINCREMENT,event_name TEXT NOT NULL,path TEXT,listing_id INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP)`),db.prepare(`CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL,expires_at INTEGER NOT NULL,created_at INTEGER DEFAULT (strftime('%s','now') * 1000))`),db.prepare('CREATE INDEX IF NOT EXISTS idx_sessions_user_expiry ON sessions(user_id,expires_at)'),db.prepare('CREATE INDEX IF NOT EXISTS idx_sessions_expiry ON sessions(expires_at)'),db.prepare(`CREATE TABLE IF NOT EXISTS otp_challenges(id INTEGER PRIMARY KEY AUTOINCREMENT,phone TEXT NOT NULL,code_hash TEXT NOT NULL,attempts INTEGER DEFAULT 0,expires_at INTEGER NOT NULL,consumed_at INTEGER)`),db.prepare(`CREATE TABLE IF NOT EXISTS favorites(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,listing_id INTEGER NOT NULL,UNIQUE(user_id,listing_id))`),db.prepare(`CREATE TABLE IF NOT EXISTS comments(id INTEGER PRIMARY KEY AUTOINCREMENT,listing_id INTEGER NOT NULL,user_id INTEGER,author_name TEXT NOT NULL,body TEXT NOT NULL,status TEXT DEFAULT 'visible',created_at TEXT DEFAULT CURRENT_TIMESTAMP)`),db.prepare(`CREATE TABLE IF NOT EXISTS reports(id INTEGER PRIMARY KEY AUTOINCREMENT,listing_id INTEGER NOT NULL,reporter_name TEXT NOT NULL,reason TEXT NOT NULL,status TEXT DEFAULT 'open',created_at TEXT DEFAULT CURRENT_TIMESTAMP)`),db.prepare(`CREATE TABLE IF NOT EXISTS conversations(id INTEGER PRIMARY KEY AUTOINCREMENT,listing_id INTEGER,buyer_id INTEGER NOT NULL,seller_id INTEGER NOT NULL,status TEXT DEFAULT 'open',updated_at TEXT DEFAULT CURRENT_TIMESTAMP)`),db.prepare(`CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY AUTOINCREMENT,conversation_id INTEGER NOT NULL,sender_id INTEGER NOT NULL,body TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP)`),db.prepare(`CREATE TABLE IF NOT EXISTS listing_images(id INTEGER PRIMARY KEY AUTOINCREMENT,listing_id INTEGER NOT NULL,file_url TEXT NOT NULL,sort_order INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP)`)]);const c=await db.prepare('SELECT COUNT(*) n FROM categories').first();if(!c.n)await db.batch(categories.map(x=>db.prepare('INSERT INTO categories(name,slug,icon) VALUES(?,?,?)').bind(x[0],x[1],x[2])));for(const migration of ["ALTER TABLE users ADD COLUMN phone_verified INTEGER DEFAULT 0","ALTER TABLE users ADD COLUMN verification_status TEXT DEFAULT 'unverified'"]){try{await db.prepare(migration).run()}catch(_error){}}const l=await db.prepare('SELECT COUNT(*) n FROM listings').first();if(!l.n){await db.prepare('INSERT INTO users(name,phone,role,district) VALUES(?,?,?,?)').bind('UMKM Kendari','081234567890','seller','Mandonga').run();await db.batch([['Rumah Minimalis Dekat UHO','Hunian strategis siap huni di Kendari',650000000,1,'Mandonga'],['iPhone 13 Kondisi Mulus','Unit normal, lengkap dengan box',7200000,2,'Kadia'],['Jasa Desain Interior Kendari','Konsultasi dan desain ruang untuk rumah Anda',1500000,6,'Kambu']].map(x=>db.prepare('INSERT INTO listings(seller_id,category_id,title,description,price,district) VALUES(1,?,?,?,?,?)').bind(x[0],x[1],x[2],x[3],x[4])));}}
const ensureSeed=db=>{if(!seedPromise)seedPromise=seed(db);return seedPromise};
const normalizeWaPhone=phone=>{const d=String(phone||'').replace(/\D/g,'');if(d.startsWith('08'))return `62${d.slice(1)}`;if(d.startsWith('8'))return `62${d}`;if(d.startsWith('62'))return d;return null};
